import os,glob,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
def load():
    G={}
    for p in glob.glob(d+'/../../sessions/*.jsonl'):
        t=open(p,errors='ignore').read().replace('\\n','\n')
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)) \((\d+)x(\d+)\):\n',t):
            k,h,w=m[1],int(m[2]),int(m[3])
            rest=t[m.end():]
            nxt=rest.find('pair') if 'pair' in rest else len(rest)
            lines=[r.split() for r in rest[:nxt].split('\n')[:h]]
            if all(len(r)==w and all(x.isdigit() for x in r) for r in lines):
                G[k]=[[int(x) for x in r] for r in lines]
    return G
G=load(); print(sorted(G))
for k in sorted(G):
    print(k, len(G[k]), 'x', len(G[k][0]))
